function alternatingArcs(colors: number[], k: number): number {
  const n = colors.length;
  let count = 0;
  for (let s = 0; s < n; s++) {
    let ok = true;
    for (let t = 1; t < k && ok; t++) {
      if (colors[(s + t) % n] === colors[(s + t - 1) % n]) ok = false;
    }
    if (ok) count++;
  }
  return count;
}

