class Solution:
    def alternatingArcs(self, colors: List[int], k: int) -> int:
        n = len(colors)
        count = 0
        for s in range(n):
            if all(colors[(s + t) % n] != colors[(s + t - 1) % n] for t in range(1, k)):
                count += 1
        return count

