function alternatingArcs(colors: number[], k: number): number {
  const n = colors.length;
  let run = 1, count = 0;
  for (let j = 1; j < n + k - 1; j++) {
    run = colors[j % n] !== colors[(j - 1) % n] ? run + 1 : 1;
    if (j >= k - 1 && run >= k) count++;
  }
  return count;
}

